export function fresh(now=Date.now()){return {version:1,at:now,cls:0,element:2,pet:1,realm:0,qi:0,stones:60,body:0,gear:0,relic:0,zone:0,wins:[0,0,0],cleared:[false,false,false],choices:[null,null,null],learned:[[],[],[]],mode:'rest',started:false};}
export function validate(d){if(!d||d.version!==1)throw Error('Phiên bản bản lưu không được hỗ trợ.');for(const [k,max] of Object.entries({at:1e15,cls:2,element:4,pet:4,realm:2,qi:1e10,stones:1e10,body:100,gear:100,relic:2,zone:2})){if(!Number.isFinite(d[k])||d[k]<0||d[k]>max||(!['qi','stones','at'].includes(k)&&!Number.isInteger(d[k])))throw Error('Bản lưu không hợp lệ: '+k);}for(const k of ['wins','cleared','choices','learned'])if(!Array.isArray(d[k])||d[k].length!==3)throw Error('Dữ liệu thiếu: '+k);if(!d.wins.every(x=>Number.isInteger(x)&&x>=0&&x<1e9)||!d.cleared.every(x=>typeof x==='boolean')||!d.choices.every(x=>[null,'heal','seal'].includes(x))||!d.learned.every(a=>Array.isArray(a)&&new Set(a).size===a.length&&a.every(x=>Number.isInteger(x)&&x>=0&&x<6)))throw Error('Dữ liệu tiến trình không hợp lệ.');if(!['rest','patrol'].includes(d.mode)||typeof d.started!=='boolean')throw Error('Dữ liệu hoạt động không hợp lệ.');if(d.zone>0&&!d.choices[d.zone-1])throw Error('Khu vực chưa mở.');return structuredClone(d);}
export const rate=s=>1+s.realm*.6+s.choices.filter(x=>x==='heal').length*.2;
export function elapsed(s,now=Date.now()){const sec=Math.max(0,Math.min(43200,(now-s.at)/1000));s.qi+=sec*rate(s);const reward=s.mode==='patrol'&&s.cleared[s.zone]?Math.floor(sec/5)*(2+s.zone):0;s.stones+=reward;s.at=Math.max(s.at,now);return {sec,qi:sec*rate(s),stones:reward};}
export function stats(s){const a=s.learned[s.cls],off=a.filter(x=>x%2===1).length,def=a.length-off;return {hp:120+s.realm*100+s.body*25+(s.cls===1?80:0)+def*12,atk:13+s.realm*12+s.gear*4+off*5+(s.cls===0?5:0),armor:s.body*2+(s.cls===1?6:0),heal:s.pet===1?3:0};}
export function affinity(a,b){return ({0:1,1:4,4:2,2:3,3:0})[a]===b?1.15:1;}
export function synergy(a,b){return ({1:3,3:4,4:0,0:2,2:1})[a]===b;}
export function attack(s,tick){const p=stats(s);let damage=p.atk*affinity(s.element,zones[s.zone].element);let skill=tick%3===0;if(skill)damage*=s.cls===0?2.3:s.cls===1?1.65:1.35;damage+=s.cls===2?10+s.realm*7:3;if(synergy(s.pet,s.element))damage*=1.12;if(s.element===3)damage+=3;if(s.relic===0&&skill)damage*=1.12;if(s.relic===2)damage*=1.08;return {damage:Math.round(damage),skill};}
export function upgrade(s,type){if(type==='realm'){const cost=[100,450][s.realm];if(s.realm>=2||s.qi<cost||(s.realm===1&&!s.cleared[0]))return false;s.qi-=cost;s.realm++;return true;}const cost=type==='body'?30+s.body*20:35+s.gear*25;if(s.stones<cost||s[type]>=100||!['body','gear'].includes(type))return false;s.stones-=cost;s[type]++;return true;}
export function learn(s,i){const a=s.learned[s.cls],cost=25+i*20;if(!Number.isInteger(i)||i<0||i>5||a.includes(i)||s.stones<cost||(i>1&&!a.includes(i-2)))return false;a.push(i);s.stones-=cost;return true;}

